<?php $titulo_pagina='Painel da Empresa';$estilos_pagina=['/assets/css/admin.css?v=5'];require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';verificarAutenticacao();if(($_SESSION['tipo_usuario']??'')!=='empresa')redirecionar('/dashboard/');$stmt=$mysqli->prepare('SELECT * FROM empresas WHERE usuario_id=?');$stmt->bind_param('i',$_SESSION['usuario_id']);$stmt->execute();$empresa=$stmt->get_result()->fetch_assoc();if($_SERVER['REQUEST_METHOD']==='POST'&&validar_csrf($_POST['csrf_token']??'')){$titulo=trim($_POST['titulo']??'');$descricao=trim($_POST['descricao']??'');$requisitos=trim($_POST['requisitos']??'');$cidade=trim($_POST['cidade']??'');$uf=mb_strtoupper(trim($_POST['uf']??''));$modalidade=$_POST['modalidade']??'presencial';$contrato=trim($_POST['tipo_contrato']??'');$salario=trim($_POST['faixa_salarial']??'');$stmt=$mysqli->prepare('INSERT INTO vagas(empresa_id,titulo,descricao,requisitos,cidade,uf,modalidade,tipo_contrato,faixa_salarial) VALUES(?,?,?,?,?,?,?,?,?)');$stmt->bind_param('issssssss',$empresa['id'],$titulo,$descricao,$requisitos,$cidade,$uf,$modalidade,$contrato,$salario);$stmt->execute();mensagem_sucesso('Vaga publicada.');redirecionar('/empresa/painel.php');}$stmt=$mysqli->prepare('SELECT v.*,(SELECT COUNT(*) FROM candidaturas c WHERE c.vaga_id=v.id) candidaturas FROM vagas v WHERE empresa_id=? ORDER BY criado_em DESC');$stmt->bind_param('i',$empresa['id']);$stmt->execute();$vagas=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);require_once __DIR__.'/../includes/header.php';?><div class="container"><div class="page-heading"><div><h1><?php echo sanitizar($empresa['nome_fantasia']); ?></h1><p>Vagas, candidatos e presença pública da empresa.</p></div><a class="btn" href="/empresa.php?id=<?php echo (int)$empresa['id']; ?>">Perfil público</a></div><?php exibir_mensagens(); ?><form class="service-form" method="POST"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><h2>Publicar vaga</h2><div class="form-grid"><div class="form-group"><label>Título</label><input name="titulo" required></div><div class="form-group"><label>Cidade</label><input name="cidade" required></div><div class="form-group form-span"><label>Descrição</label><textarea name="descricao" required></textarea></div><div class="form-group form-span"><label>Requisitos</label><textarea name="requisitos"></textarea></div><div class="form-group"><label>UF</label><input name="uf" maxlength="2"></div><div class="form-group"><label>Modalidade</label><select name="modalidade"><option>presencial</option><option>hibrido</option><option>remoto</option></select></div><div class="form-group"><label>Contrato</label><input name="tipo_contrato" placeholder="CLT, PJ, estágio"></div><div class="form-group"><label>Faixa salarial</label><input name="faixa_salarial"></div></div><button class="btn">Publicar vaga</button></form><div class="dashboard-menu"><?php foreach($vagas as $vaga): ?><article class="card"><h3><?php echo sanitizar($vaga['titulo']); ?></h3><p><?php echo (int)$vaga['candidaturas']; ?> candidaturas</p><a href="/empresa/candidatos.php?vaga=<?php echo (int)$vaga['id']; ?>">Ver candidatos</a></article><?php endforeach; ?></div></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
